Component.YAML:
display:
  - platform: addressable_light
    id: led_matrix_display
    addressable_light_id: led_matrix_light
    width: 8
    height: 8
    rotation: 180°
    update_interval: 16ms
    lambda: |-
          // Draw a bulls-eye pattern
          Color red = Color(0xFF0000);
          Color green = Color(0x00FF00);
          Color blue = Color(0x0000FF);
          it.rectangle(0, 0, 8, 8, red);
          it.rectangle(1, 1, 6, 6, green);
          it.rectangle(2, 2, 4, 4, blue);
          it.rectangle(3, 3, 2, 2, red);

api: # https://esphome.io/components/api.html id: api_component # Optional identifier port: 6053 # Default port for ESPHome Native API password: !secret api_password # (Optional) password for protecting API access encryption: key: !secret api_encryption_key # 16-byte key (Base64 encoded) for secure communication reboot_timeout: 0s # Disable auto-reboot if API disconnected (0s = disabled) debug: false # Enable low-level API message logging services: - service: set_led_brightness variables: brightness: int then: - logger.log: "Setting LED brightness from API" - lambda: |- id(my_led).set_level(brightness / 100.0f);
- service: reboot_device then: - logger.log: "Reboot requested via API" - button.press: restart_button
on_client_connected: - logger.log: "Home Assistant connected to device" on_client_disconnected: - logger.log: "Home Assistant disconnected"

esp32_ble_server: manufacturer: "Orange" # Manufacturer name (default ESPHome) model: "ESP32 Model X" # Model name (default project or board name) appearance: 0 # Appearance value in advertising data (default 0) firmware_version: "1.0.0" # Firmware version (default ESPHome version) manufacturer_data: [0x4C, 0, 0x23, 77, 0xF0] # Manufacturer-specific advertising data
on_connect: - lambda: |- ESP_LOGD("BLE", "Connection from %d", id);
on_disconnect: - lambda: |- ESP_LOGD("BLE", "Disconnection from %d", id);
services: - uuid: "2a24b789-7aab-4535-af3e-ee76a35cc42d" # Service UUID advertise: false # Whether to advertise this service characteristics: - uuid: "cad48e28-7fbe-41cf-bae9-d77a6c233423" # Characteristic UUID id: test_characteristic description: "Sample description" read: true write: false broadcast: false notify: false indicate: false write_no_response: false value: data: "Hello, World!" type: string string_encoding: utf-8 descriptors: - uuid: "cad48e28-7fbe-41cf-bae9-d77a6c211423" id: test_descriptor value: data: "Hello, World Descriptor!" on_write: then: - lambda: |- ESP_LOGD("BLE", "Characteristic written by client");
# Actions
# ble_server.characteristic.set_value - set characteristic value # ble_server.characteristic.notify - notify clients of characteristic update # ble_server.descriptor.set_value - set descriptor value

# Minimal example configuration with common sensors
i2c:

bme680_bsec:

sensor:
  - platform: bme680_bsec
    temperature:
      name: "BME680 Temperature"
    pressure:
      name: "BME680 Pressure"
    humidity:
      name: "BME680 Humidity"
    iaq:
      name: "BME680 IAQ"
      id: iaq
    co2_equivalent:
      name: "BME680 CO2 Equivalent"
    breath_voc_equivalent:
      name: "BME680 Breath VOC Equivalent"

text_sensor:
  - platform: bme680_bsec
    iaq_accuracy:
      name: "BME680 IAQ Accuracy"

  - platform: template
    name: "BME680 IAQ Classification"
    icon: "mdi:checkbox-marked-circle-outline"
    lambda: |-
      if ( int(id(iaq).get_state()) <= 50) {
        return {"Excellent"};
      }
      else if (int(id(iaq).get_state()) >= 51 && int(id(iaq).get_state()) <= 100) {
        return {"Good"};
      }
      else if (int(id(iaq).get_state()) >= 101 && int(id(iaq).get_state()) <= 150) {
        return {"Lightly polluted"};
      }
      else if (int(id(iaq).get_state()) >= 151 && int(id(iaq).get_state()) <= 200) {
        return {"Moderately polluted"};
      }
      else if (int(id(iaq).get_state()) >= 201 && int(id(iaq).get_state()) <= 250) {
        return {"Heavily polluted"};
      }
      else if (int(id(iaq).get_state()) >= 251 && int(id(iaq).get_state()) <= 350) {
        return {"Severely polluted"};
      }
      else if (int(id(iaq).get_state()) >= 351) {
        return {"Extremely polluted"};
      }
      else {
        return {"error"};
      }

display:
  - platform: ...
    # ...
    lambda: |-
      // Write your display rendering code here

      // For example, draw a line from [x=0,y=0] to [x=50,y=50]
      it.line(0, 0, 50, 50);

# Example configuration entry display: - platform: lcd_pcf8574 id: my_lcd # ... lambda: |- id(my_lcd_menu).draw(); if (!id(my_lcd_menu).is_active()) it.print("Menu is not active");
# Declare a LCD menu lcd_menu: id: my_lcd_menu display_id: my_lcd active: true mode: rotary on_enter: then: lambda: 'ESP_LOGI("display_menu", "root enter");' on_leave: then: lambda: 'ESP_LOGI("display_menu", "root leave");' items: - type: back text: 'Back' - type: label text: 'Label 1' - type: label text: !lambda |- return "Templated label";
# Encoder to provide navigation sensor: - platform: rotary_encoder # ... on_anticlockwise: - display_menu.up: on_clockwise: - display_menu.down:
# A de-bounced GPIO is used to 'click' binary_sensor: - platform: gpio # ... filters: - delayed_on: 10ms - delayed_off: 10ms on_press: - display_menu.enter:

esp32_ble_tracker: max_connections: 3 # Maximum number of BLE connection slots (default 3, max 9 on esp-idf) scan_parameters: interval: 320ms # Time spent scanning each BLE channel (default 320ms) window: 30ms # Time actively listening per scan interval (default 30ms) duration: 5min # Total scan duration for debugging (default 5min) active: true # Whether to actively send scan requests (default true) continuous: true # Whether to scan continuously or only on command (default true) software_coexistence: true # Prioritize BLE over Wi-Fi on connection start (default true)
# Automations triggered on BLE data reception events on_ble_advertise: - mac_address: - XX:XX:XX:XX:XX:XX # Filter for specific MAC addresses (optional) then: - lambda: |- ESP_LOGD("ble_adv", "New BLE device"); ESP_LOGD("ble_adv", " address: %s", x.address_str().c_str()); ESP_LOGD("ble_adv", " name: %s", x.get_name().c_str()); // Additional logging of advertised services and data
on_ble_manufacturer_data_advertise: - mac_address: XX:XX:XX:XX:XX:XX manufacturer_id: 0590 # Manufacturer ID then: - lambda: |- if (x[0] != 0x7b || x[1] != 0x61) return; int value = x[2] + (x[3] << 8); id(ble_sensor).publish_state(value);
on_ble_service_data_advertise: - mac_address: XX:XX:XX:XX:XX:XX service_uuid: 181A then: - lambda: 'id(ble_sensor).publish_state(x[0]);'
on_scan_end: - then: - lambda: |- ESP_LOGD("ble_auto", "The scan has ended!");
# Actions to control scanning # esp32_ble_tracker.start_scan - start BLE scan # esp32_ble_tracker.stop_scan - stop BLE scan

# Example configuration entry
esp32_ble_tracker:

exposure_notifications:
  on_exposure_notification:
    then:
      - lambda: |
          ESP_LOGD("main", "Got notification:");
          ESP_LOGD("main", "  RPI: %s", format_hex_pretty(x.rolling_proximity_identifier).c_str());
          ESP_LOGD("main", "  RSSI: %d", x.rssi);

i2c: sda: 4 scl: 5 scan: True
i2c_device: id: i2cdev address: 0x2C
on_...: then: - lambda: !lambda |- id(i2cdev).write_byte(0x00, 0x12); if (auto b = id(i2cdev).read_byte(0x01)) { // TODO }

on_...:
- http_request.get:
    url: https://esphome.io
    capture_response: true
    on_response:
      then:
        - lambda: |-
            json::parse_json(body, [](JsonObject root) -> bool {
                if (root["vol"]) {
                    id(player_volume).publish_state(root["vol"]);
                    return true;
                }
                else {
                  ESP_LOGD(TAG,"No 'vol' key in this json!");
                  return false;
                }
            });

# Example configuration entry
filters:
  - lambda: return x * (9.0/5.0) + 32.0;

# Example configuration entry display: - platform: lcd_pcf8574 id: my_lcd dimensions: 20x4 # ... user_characters: - position: 0 data: # mark_back symbol - 0b00100 - 0b01000 - 0b11110 - 0b01001 - 0b00101 - 0b00001 - 0b11110 - 0b00000 lambda: |- id(my_lcd_menu).draw(); if (!id(my_lcd_menu).is_active()) it.print("Menu is not active");
# Declare a LCD menu lcd_menu: id: my_lcd_menu display_id: my_lcd active: true mode: rotary mark_back: 0x08 mark_selected: 0x3e mark_editing: 0x2a mark_submenu: 0x7e items: # ... # Rotary encoder to provide navigation sensor: - platform: rotary_encoder # ... filters: debounce: 30ms on_anticlockwise: - display_menu.up: on_clockwise: - display_menu.down:
# A debounced GPIO push button is used to 'click' binary_sensor: - platform: gpio # ... filters: - delayed_on: 30ms - delayed_off: 30ms on_press: - display_menu.enter:

# Example configuration entry mapping: - id: weather_icon from: string to: image default_value: unknown_weather_img entries: clear-night: clear_night_img cloudy: cloudy_img
- id: day_map from: int to: string entries: 1: DIM 2: LUN 3: MAR 4: MER 5: JEU 6: VEN 7: SAM default_value: "---"
# Using the mapping in an automation text_sensor: - id: forecast_text platform: homeassistant entity_id: weather.forecast_home on_value: lvgl.image.update: id: weather_image src: !lambda return id(weather_icon)[x];

# example
lambda: |-
  ESP_LOGD("Reg1000", "Received value %lld", x);
  ESP_LOGD("Reg1000", "Parsed from bytes 0x%x;0x%x", data[item->offset], data[item->offset + 1]);
  if (x > 3) {
    return std::string("Three");
  }

text_sensor:
  - platform: modbus_controller
    modbus_controller_id: modbus_device
    id: reg_1002_text
    bitmask: 0
    register_type: holding
    address: 1002
    raw_encode: HEXBYTES
    name: Register 1002 (Text)
    lambda: |-
      uint16_t value = modbus_controller::word_from_hex_str(x, 0);
      switch (value) {
        case 1: return std::string("ready");
        case 2: return std::string("EV is present");
        case 3: return std::string("charging");
        case 4: return std::string("charging with ventilation");
        default: return std::string("Unknown");
      }
      return x;

